document.addEventListener("DOMContentLoaded", () => {
   if (document.body.dataset.pageId !== "login-register") {
     return;
   }

   // Remove the empty values generated by Keycloak's checkbox renderers
   document.querySelector("#ageconfirm-empty")?.remove();
   document.querySelector("#terms-empty")?.remove();

   const termsLabel = document.querySelector('label[for="terms-true"]');

   if (termsLabel) {
      const urls = {
         terms: "https://www.europeana.eu/rights/terms-of-use",
         privacy: "https://www.europeana.eu/rights/privacy-statement"
      };

      const text = termsLabel.textContent;
      const pattern = /\[\[(terms|privacy):([^\]]*)\]\]/g;
      const fragment = document.createDocumentFragment();

      let lastIndex = 0;

      for (const match of text.matchAll(pattern)) {
         fragment.append(document.createTextNode(
            text.slice(lastIndex, match.index)
         ));

         const link = document.createElement("a");
         link.href = urls[match[1]];
         link.textContent = match[2];
         link.target = "_blank";
         link.rel = "noopener noreferrer";

         fragment.append(link);
         lastIndex = match.index + match[0].length;
      }

      fragment.append(document.createTextNode(text.slice(lastIndex)));
      termsLabel.replaceChildren(fragment);
   }
});
